  "code": "\n  (function () {\n    if (window.__snzFaqReady) return;\n    window.__snzFaqReady = true;\n    document.addEventListener('click', function (e) {\n      var btn = e.target && e.target.closest ? e.target.closest('.snz-faq__btn') : null;\n      if (!btn) return;\n      var item = btn.closest('.snz-faq__item'); var list = btn.closest('.snz-faq');\n      if (!item || !list) return;\n      var open = !item.classList.contains('is-open');\n      var items = list.querySelectorAll('.snz-faq__item');\n      for (var i = 0; i < items.length; i++) {\n        var it = items[i]; var b = it.querySelector('.snz-faq__btn'); var on = open && it === item;\n        it.classList.toggle('is-open', on);\n        if (b) b.setAttribute('aria-expanded', on ? 'true' : 'false');\n      }\n    }, false);\n  })();\n"
